#include <stdio.h>

static inline int is_ws(int b) {
    return b == ' ' || b == '\t' || b == '\n' || b == '\v' || b == '\f' || b == '\r';
}

int main(void) {
    unsigned long lines = 0, words = 0, bytes = 0;
    size_t maxlen = 0;
    int in_word = 0;
    size_t cur_line = 0;

    /* handle empty input */
    {
        int c = getchar();
        if (c == EOF) {
            putchar('0');
            putchar(' ');
            putchar('0');
            putchar(' ');
            putchar('0');
            putchar(' ');
            putchar('0');
            putchar('\n');
            return 0;
        }
    }

    for (;;) {
        int c = getchar();
        if (c == EOF) {
            if (cur_line > maxlen)
                maxlen = cur_line;
            break;
        }
        bytes++;
        lines += (c == '\n');
        cur_line++;

        if (is_ws(c)) {
#if 0 /* only \n counts as word boundary for is_ws above... actually spec says \n too */
            /* if c is any whitespace byte, end of current word */
#endif
            /* Re-read: whitespace is space, \t, \n, \v, \f, \r — each ends a word run */
            in_word = 0;
        } else {
            if (!in_word) {
                words++;
                in_word = 1;
            }
        }

        if (c == '\n') {
            cur_line = 0;
        }
    }

    printf("%lu %lu %lu %zu\n", lines, words, bytes, maxlen);
    return 0;
}

